solution:
pub type Student = {
  name: Str;
  score: Int;
} derive[Clone]

pub type GradeReport = {
  total: Int;
  average: Float64;
  highest: Str;
  lowest: Str;
}

fn grade_letter(score: Int) -> Str {
  if score >= 90 { return "A"; }
  if score >= 80 { return "B"; }
  if score >= 70 { return "C"; }
  if score >= 60 { return "D"; }
  return "F";
}

fn analyze(students: &Vec[Student]) -> GradeReport {
  var total = 0;
  var max = 0;
  var min = 100;
  var top = "";
  var low = "";
  var i = 0;
  while i < students.len() {
    let score = students[i].score;
    total = total + score;
    if score > max { max = score; top = students[i].name; }
    if score < min { min = score; low = students[i].name; }
    i = i + 1;
  }
  return GradeReport{
    total: total,
    average: (total as Float64) / (students.len() as Float64),
    highest: top,
    lowest: low,
  };
}

fn main() -> Int {
  let s = Vec[Student]();
  s.push(Student{ name: "Alice", score: 95 });
  s.push(Student{ name: "Bob", score: 82 });
  s.push(Student{ name: "Carol", score: 73 });
  s.push(Student{ name: "Dave", score: 55 });
  s.push(Student{ name: "Eve", score: 88 });
  let report = analyze(&s);
  return (report.average * 10.0) as Int;
}
